codeExamples.code:
// Get all items from previous nodes
const items = $input.all();

// Filter items where price > 100
const highValueItems = items
  .map(item => item.json)  // Extract the json data
  .filter(data => data.price > 100);  // Keep only expensive items

// Return in n8n format
return highValueItems.map(item => ({ json: item }));

// Example: API returns users with firstName and lastName
// We want fullName instead

const users = $input.all().map(item => item.json);

const transformedUsers = users.map(user => ({
  id: user.id,
  fullName: `${user.firstName} ${user.lastName}`,
  email: user.email
}));

return transformedUsers.map(user => ({ json: user }));

// Find a specific user by email
const users = $input.all().map(item => item.json);
const targetEmail = 'john@example.com';

const foundUser = users.find(user => user.email === targetEmail);

if (foundUser) {
  return [{ json: { found: true, user: foundUser } }];
} else {
  return [{ json: { found: false, message: 'User not found' } }];
}

