practice.solution:
const todos = [
  { id: 1, task: 'Learn JavaScript', completed: false, priority: 'high' },
  { id: 2, task: 'Build n8n workflow', completed: true, priority: 'high' },
  { id: 3, task: 'Read docs', completed: false, priority: 'low' },
  { id: 4, task: 'Practice arrays', completed: false, priority: 'high' }
];

const filtered = todos
  .filter(todo => !todo.completed)
  .filter(todo => todo.priority === 'high')
  .map(todo => ({ id: todo.id, task: todo.task }));

return [{ json: { highPriorityTodos: filtered, count: filtered.length } }];

