// API returns: { userId: 123, firstName: 'John', lastName: 'Doe', email: 'john@example.com' }
// We want: { id: 123, fullName: 'John Doe', contact: { email: '...' } }

const apiResponse = $json;

const restructured = {
  id: apiResponse.userId,
  fullName: `${apiResponse.firstName} ${apiResponse.lastName}`,
  contact: {
    email: apiResponse.email
  },
  metadata: {
    processedAt: new Date().toISOString(),
    source: 'api'
  }
};

return [{ json: restructured }];

// Input: { user: { profile: { name: 'Alice', email: 'alice@example.com' } } }
// Output: { name: 'Alice', email: 'alice@example.com' }

const input = $json;

const flattened = {
  name: input.user.profile.name,
  email: input.user.profile.email
};

return [{ json: flattened }];

// Combine data from multiple sources
const userData = $node['Get User'].json;
const orderData = $node['Get Orders'].json;
const enrichmentData = {
  processingDate: new Date().toISOString(),
  version: '1.0'
};

const combined = {
  ...userData,
  orders: orderData,
  ...enrichmentData
};

return [{ json: combined }];

// Access object properties dynamically
const data = $json;
const fieldToExtract = 'email'; // Could come from settings

const value = data[fieldToExtract];

return [{
  json: {
    field: fieldToExtract,
    value: value,
    exists: value !== undefined
  }
}];

practice.instructions:
You receive this complex nested object from an API:

```json
{
  "data": {
    "user": {
      "personal": {
        "firstName": "John",
        "lastName": "Doe",
        "age": 30
      },
      "contact": {
        "email": "john@example.com",
        "phone": "555-0123"
      }
    },
    "subscription": {
      "tier": "premium",
      "active": true
    }
  }
}
```

Transform it into this flat structure:
```json
{
  "fullName": "John Doe",
  "email": "john@example.com",
  "phone": "555-0123",
  "isPremium": true,
  "age": 30
}
```

