const apiResponse = $json;

const transformed = {
  fullName: `${apiResponse.data.user.personal.firstName} ${apiResponse.data.user.personal.lastName}`,
  email: apiResponse.data.user.contact.email,
  phone: apiResponse.data.user.contact.phone,
  isPremium: apiResponse.data.subscription.tier === 'premium' && apiResponse.data.subscription.active,
  age: apiResponse.data.user.personal.age
};

return [{ json: transformed }];
